 "content": "from collections import Counter


def _bands(length, active):
    bands = []
    start = None
    for i in range(length):
        if active(i):
            if start is None:
                start = i
        elif start is not None:
            bands.append((start, i - 1))
            start = None
    if start is not None:
        bands.append((start, length - 1))
    return bands


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rb = _bands(h, lambda r: any(grid[r][c] != 0 for c in range(w)))
    cb = _bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))

    nonzero = Counter(v for row in grid for v in row if v != 0)
    if not nonzero:
        return out
    frame = nonzero.most_common(1)[0][0]

    # The repeated objects have a one-cell frame. Their common interior color
    # is the background fill; other uniform interior colors are line markers.
    interiors = []
    for r0, r1 in rb:
        for c0, c1 in cb:
            cells = [grid[r][c]
                     for r in range(r0 + 1, r1)
                     for c in range(c0 + 1, c1)
                     if grid[r][c] not in (0, frame)]
            interiors.extend(cells)
    if not interiors:
        return out
    base = Counter(interiors).most_common(1)[0][0]

    markers = {}
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            vals = [grid[r][c]
                    for r in range(r0 + 1, r1)
                    for c in range(c0 + 1, c1)
                    if grid[r][c] not in (0, frame)]
            if vals:
                color, count = Counter(vals).most_common(1)[0]
                if color != base and count == len(vals):
                    markers[(ri, ci)] = color

    # Join aligned matching markers, painting only the blank separator bands.
    for ri, (r0, r1) in enumerate(rb):
        inner_rows = range(r0 + 1, r1)
        for r in inner_rows:
            for color in set(markers.get((ri, ci)) for ci in range(len(cb))):
                if color is None:
                    continue
                positions = [ci for ci in range(len(cb))
                             if markers.get((ri, ci)) == color]
                if len(positions) < 2:
                    continue
                for ci in range(min(positions), max(positions)):
                    left_end = cb[ci][1]
                    right_start = cb[ci + 1][0]
                    for c in range(left_end + 1, right_start):
                        if out[r][c] == 0:
                            out[r][c] = color

    for ci, (c0, c1) in enumerate(cb):
        inner_cols = range(c0 + 1, c1)
        for c in inner_cols:
            for color in set(markers.get((ri, ci)) for ri in range(len(rb))):
                if color is None:
                    continue
                positions = [ri for ri in range(len(rb))
                             if markers.get((ri, ci)) == color]
                if len(positions) < 2:
                    continue
                for ri in range(min(positions), max(positions)):
                    upper_end = rb[ri][1]
                    lower_start = rb[ri + 1][0]
                    for r in range(upper_end + 1, lower_start):
                        if out[r][c] == 0:
                            out[r][c] = color
    return out
